import{z as s,x as l,o as E,c as d,q as n,j as A,D as e,d as t,s as B,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"模拟矩方法","description":"","frontmatter":{"title":"模拟矩方法","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/se-smm.md","filePath":"econ/se-smm.md","lastUpdated":1791413859000}'),m={name:"econ/se-smm.md"};function c(p,a,h,F,D,u){const o=l("Mermaid");return E(),d("div",null,[a[2]||(a[2]=n('<h1 id="模拟矩方法" tabindex="-1">模拟矩方法 <a class="header-anchor" href="#模拟矩方法" aria-label="Permalink to &quot;模拟矩方法&quot;">​</a></h1><div class="epigraph"><p>模型里的积分算不动，就用抽样代替；模拟误差必须以抽样的速度消失、并走进标准误，否则估计可以一致，推断却在说谎。</p><footer>—— 据 McFadden, Econometrica 1989；Pakes and Pollard, Econometrica 1989 整理</footer></div><p><a href="/econ/se-bayesian-structural">上一课</a>换了估计原则，但四课装置还有一个共同的数字尾巴：积分。BLP 的份额是 \\(\\beta_i\\) 上的积分，动态选择的期望值函数是状态上的积分，拍卖反演要核密度，模拟似然以抽样为引擎。本课把这些散在各课的模拟收拢成一门方法：<a href="/econ/gmm-econ">GMM</a> 的框架不动，只是内层期望换成蒙特卡洛平均，而模拟误差要进渐近分布。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写出 \\(\\mathbb{E}[g(W,\\theta)]=0\\) 容易，算出 \\(g\\) 难：份额积分维度随产品特征走，动态积分维度随状态空间走，数值积分在四维以上就不可行。用抽样平均</p> \\[\\hat g(\\theta) \\;=\\; \\frac{1}{R}\\sum_{r=1}^{R} g(\\theta,\\omega^r) \\]<p>代替，代价有二：目标函数随抽样抖动，换一批 \\(\\omega\\) 最优点就搬家，优化器在噪声上找零点；渐近方差多出模拟项——\\(R\\) 有限时标准误要乘修正因子，否则置信区间过窄。</p><p><span class="marginnote">术语翻译：蒙特卡洛平均就是「算不动的期望用掷骰子代替」——从分布里抽 \\(R\\) 个点，把函数值平均起来当期望。代价是这批骰子带来的抖动会跟着走进估计：目标函数变成随机的，换一批点，最优解就搬一次家。</span></p><h3 id="平滑、公共随机数与抽法" tabindex="-1">平滑、公共随机数与抽法 <a class="header-anchor" href="#平滑、公共随机数与抽法" aria-label="Permalink to &quot;平滑、公共随机数与抽法&quot;">​</a></h3><p>三件套管理模拟误差。公共随机数：全参数路径用同一批 \\(\\omega^r\\)，目标函数对 \\(\\theta\\) 连续（否则纯噪声），优化器才有的找。抽法：Halton 序列等拟蒙特卡洛在同样 \\(R\\) 下覆盖更均匀，Train 的模拟估计教材给了系统对照。偏差阶：McFadden 1989 的模拟矩估计要求 \\(R\\) 随 \\(n\\) 增长，偏差与方差都写进极限分布；\\(R\\) 固定则估计带模拟偏差，不能再当一致估计报告。</p><p><span class="marginnote">间接推断是 SMM 的近亲：用一个灵活的辅助模型（如 VAR 或简化式 logit）拟真实数据，再用结构模型模拟出数据拟同一辅助模型，以辅助参数的距离为目标。Gourieroux–Monfort 的间接推断与 McFadden 的 MSM 同属模拟估计家族，<a href="/econ/calibration-moments">校准与矩匹配</a>课提过这门亲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实施清单：固定随机种子与抽法（可复现）；选 \\(R\\) 并报告敏感性——\\(R\\) 翻倍，估计动多少；两步最优权重用含模拟项的协方差（否则 \\(J\\) 的水平失真）；模拟似然的情形（动态离散选择、多元 probit）用 McFadden 1989 的平滑模拟频率或 GHK 递归，选择概率的模拟估计以 \\(R^{1/2}\\) 级收敛。反事实同样带模拟误差：均衡重解后的福利差要连同抽样的不确定性一起自举或后验化。</p><p><span class="marginnote">数字实例：模拟误差按 \\(1/\\sqrt{R}\\) 缩小——\\(R=100\\) 时约是单次波动的 10%，\\(R=10000\\) 时缩到 1%。要让模拟噪声与抽样误差同速消失，\\(R\\) 必须随样本量一起涨；\\(R\\) 固定的估计即使样本无限大，也停不到真值上。</span></p>',14)),(E(),A(i,null,{default:e(()=>[B(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E7%A7%AF%E5%88%86%3A%20%E4%BB%BD%E9%A2%9D%20%2F%20EV%20%2F%20%E5%8F%8D%E6%BC%94%22%5D%20--%3E%20MC%5B%22%E5%9B%BA%E5%AE%9A%E7%A7%8D%E5%AD%90%E6%8A%BD%E6%A0%B7%20R%20%E6%AC%A1%22%5D%0A%20%20MC%20--%3E%20OBJ%5B%22%E6%A8%A1%E6%8B%9F%E7%9F%A9%E7%9B%AE%E6%A0%87%20%2B%20%E6%9D%83%E9%87%8D%E5%90%AB%E6%A8%A1%E6%8B%9F%E9%A1%B9%22%5D%0A%20%20OBJ%20--%3E%20OPT%5B%22%E5%85%AC%E5%85%B1%E9%9A%8F%E6%9C%BA%E6%95%B0%E4%B8%8B%E4%BC%98%E5%8C%96%22%5D%0A%20%20OPT%20--%3E%20SE%5B%22%E6%A0%87%E5%87%86%E8%AF%AF%E4%B9%98%E6%A8%A1%E6%8B%9F%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20RI%5B%22R%20%E7%9A%84%E5%A2%9E%E9%95%BF%E7%8E%87%E4%B8%8E%E5%81%8F%E5%B7%AE%E9%98%B6%22%5D%20--%3E%20SE%0A%20%20SE%20--%3E%20CF%5B%22%E5%8F%8D%E4%BA%8B%E5%AE%9E%E7%9A%84%E8%87%AA%E4%B8%BE%E5%8C%BA%E9%97%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"机制是偏差与方差的交换。模拟误差以 \\(1/\\sqrt{R}\\) 的速度进估计；公共随机数把「不同 \\(\\theta\\) 的比较」从蒙特卡洛噪声里解放出来——份额预测、策略函数的比较是差分，差分吃掉共同噪声。这正是模拟在结构模型里比在描述统计里更有用的原因：要的是 \\(\\theta\\) 变动前后的一致比较，不是绝对水平。效率的思想照旧：抽样密集区应靠近矩敏感区。",-1)),(E(),A(i,null,{default:e(()=>[B(o,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20TA%5B%22%E5%8F%82%E6%95%B0%E5%80%BC%20%CE%B8_A%22%5D%20--%3E%20CA%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E9%9A%8F%E6%9C%BA%E6%95%B0%E4%B8%8B%E7%9A%84%E6%A8%A1%E6%8B%9F%E7%9F%A9%22%5D%0A%20%20TB%5B%22%E5%8F%82%E6%95%B0%E5%80%BC%20%CE%B8_B%22%5D%20--%3E%20CB%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E9%9A%8F%E6%9C%BA%E6%95%B0%E4%B8%8B%E7%9A%84%E6%A8%A1%E6%8B%9F%E7%9F%A9%22%5D%0A%20%20CA%20--%3E%20DIF%5B%22%E5%AF%B9%20%CE%B8%20%E5%B7%AE%E5%88%86%22%5D%0A%20%20CB%20--%3E%20DIF%0A%20%20DIF%20--%3E%20KILL%5B%22%E5%85%B1%E5%90%8C%E7%9A%84%E9%AA%B0%E5%AD%90%E5%99%AA%E5%A3%B0%E4%BA%92%E7%9B%B8%E6%8A%B5%E6%B6%88%22%5D%0A%20%20DIF%20--%3E%20SIG%5B%22%E5%89%A9%E4%B8%8B%E7%9A%84%E5%8F%AA%E6%9C%89%E5%8F%82%E6%95%B0%E5%B7%AE%E5%BC%82%E7%9A%84%E4%BF%A1%E5%8F%B7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p>与<a href="/econ/calibration-moments">校准</a>的分界在推断：矩匹配不优化、不报标准误，SMM 优化并完整报渐近分布；与<a href="/econ/se-bayesian-structural">上一课</a>的接口是模拟矩也可以定义后验，两套口径对照报。</p><p><span class="marginnote">常见误区：初学者容易以为「固定随机种子 = 消除了抽样噪声」。种子固定只保证别人能复现你同一份抖动，抖动本身还在；\\(R\\) 太小或标准误漏乘修正因子，置信区间照样说谎。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(R\\) 有限时「一致」是渐近修辞，报告要带 \\(R\\) 敏感性。模拟不救识别：矩仍要能分开参数，\\(J\\) 仍只是过度识别约束的内部一致。多元 probit 的 GHK、动态模型不动点内嵌模拟，各有专门文献，本课只立框架。不要把种子固定误当纯度——种子固定为可复现，不消除抽样噪声。</p><p>后课默认：带积分的模型一律声明抽法、\\(R\\)、公共随机数与模拟修正；推断不装作没有模拟误差。下一课结构模型的验证：矩拟合之后，反事实凭什么可信。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SMM = GMM 框架 + 内层期望换抽样平均，框架不变。</li><li>模拟误差进点估计（\\(R\\) 的增长条件）与标准误（修正因子）。</li><li>公共随机数与拟蒙特卡洛管理目标函数的抖动。</li><li>间接推断用辅助模型参数做目标，与 MSM 同族。</li><li>出处：McFadden, <em>Econometrica</em> 1989；Pakes and Pollard, <em>Econometrica</em> 1989；Train, <em>Discrete Choice Methods with Simulation</em>；Gourieroux–Monfort 的间接推断。</li></ul>',7))])}const _=s(m,[["render",c]]);export{f as __pageData,_ as default};
